// Stores an EMA credential's access token as the copies sealed under the
// decided transition generation. Run it in the transaction of the statement
// that published the slot, which owns updated_at, the slot's
// compare-and-swap version; this statement changes nothing else. No rows means
// the slot is gone, belongs to another organization, or the transition moved
// since the decision.
func (q *Queries) SetEMACredentialAccessToken(ctx context.Context, arg SetEMACredentialAccessTokenParams) (SetEMACredentialAccessTokenRow, error) {
	row := q.db.QueryRow(ctx, setEMACredentialAccessToken,
		arg.PlatformCopy,
		arg.OrgCopy,
		arg.ID,
		arg.OrganizationID,
		arg.DecidedGeneration,
	)
	var i SetEMACredentialAccessTokenRow
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.UpdatedAt,
		&i.AccessTokenEncrypted,
		&i.AccessTokenOrgEncrypted,
	)
	return i, err
}

const setRemoteSessionTokens = `-- name: SetRemoteSessionTokens :one

UPDATE remote_sessions AS s
SET
    access_token_encrypted = $1::text,
    access_token_org_encrypted = $2::text,
    refresh_token_encrypted = CASE
        WHEN $3::boolean THEN $4::text
        ELSE s.refresh_token_encrypted END,
    refresh_token_org_encrypted = CASE
        WHEN $3::boolean THEN $5::text
        ELSE s.refresh_token_org_encrypted END
WHERE s.id = $6
  AND s.organization_id IS NOT DISTINCT FROM $7::text
  AND s.deleted IS FALSE
  AND COALESCE((
    SELECT t.generation FROM organization_encryption_transitions AS t
    WHERE t.organization_id = s.organization_id AND t.use_case = 'oauth-session-tokens'
    FOR KEY SHARE
  ), 0) = $8
RETURNING id, grant_generation, subject_urn, user_session_issuer_id, remote_session_client_id, organization_id, access_token_encrypted, access_token_org_encrypted, access_expires_at, refresh_token_encrypted, refresh_token_org_encrypted, authorization_expires_at, refresh_expires_at, scopes, resource, auto_refresh, last_refresh_attempt_at, last_used_at, upstream_subject, upstream_email, upstream_display_name, identity_source, enrichment, last_validated_at, validation_status, validation_reason, created_at, updated_at, deleted_at, deleted
`

type SetRemoteSessionTokensParams struct {
	AccessPlatformCopy  pgtype.Text
	AccessOrgCopy       pgtype.Text
	ReplaceRefreshToken bool
	RefreshPlatformCopy pgtype.Text
	RefreshOrgCopy      pgtype.Text
	ID                  uuid.UUID
	OrganizationID      pgtype.Text
	DecidedGeneration   int64
}

// Every write of a stored upstream OAuth token: both copies of each value
// (the *_encrypted column under the platform key, the *_org_encrypted column
// under the organization's key). Package upstreamtokens calls these queries
// and owns the sealing rules, and its tests check that every write here is
// fenced on the organization's transition generation. Statements elsewhere
// may only erase a value, by setting both of its copies to NULL.
//
// The fence compares the transition's organization with the row's own
// organization_id. A row without one (a session under a global client) finds
// no transition row and reads generation 0, the only generation such a row is
// sealed under.
// Stores the access token, and the refresh token when replace_refresh_token
// is set, as the copies sealed under the decided transition generation. A
// refresh token that is not replaced keeps both stored copies as they are.
// Run it in the transaction of the statement that created or changed the
// session, which owns updated_at; this statement changes nothing else. No
// rows means the session is gone, belongs to another organization, or the
// transition moved since the decision; the caller tells them apart by reading
// the transition again.
func (q *Queries) SetRemoteSessionTokens(ctx context.Context, arg SetRemoteSessionTokensParams) (RemoteSession, error) {
	row := q.db.QueryRow(ctx, setRemoteSessionTokens,
		arg.AccessPlatformCopy,
		arg.AccessOrgCopy,
		arg.ReplaceRefreshToken,
		arg.RefreshPlatformCopy,
		arg.RefreshOrgCopy,
		arg.ID,
		arg.OrganizationID,
		arg.DecidedGeneration,
	)
	var i RemoteSession
	err := row.Scan(
		&i.ID,
		&i.GrantGeneration,
		&i.SubjectUrn,
		&i.UserSessionIssuerID,
		&i.RemoteSessionClientID,
		&i.OrganizationID,
		&i.AccessTokenEncrypted,
		&i.AccessTokenOrgEncrypted,
		&i.AccessExpiresAt,
		&i.RefreshTokenEncrypted,
		&i.RefreshTokenOrgEncrypted,
		&i.AuthorizationExpiresAt,
		&i.RefreshExpiresAt,
		&i.Scopes,
		&i.Resource,
		&i.AutoRefresh,
		&i.LastRefreshAttemptAt,
		&i.LastUsedAt,
		&i.UpstreamSubject,
		&i.UpstreamEmail,
		&i.UpstreamDisplayName,
		&i.IdentitySource,
		&i.Enrichment,
		&i.LastValidatedAt,
		&i.ValidationStatus,
		&i.ValidationReason,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.Deleted,
	)
	return i, err
}

